import uuid
from datetime import date

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.db.database import get_db
from app.schemas.payment import ReportePendientesResponse
from app.services.report_service import ReportService

router = APIRouter(prefix="/reportes", tags=["Reportes"])


def _parse_company_id(empresa_id: str) -> uuid.UUID:
    try:
        return uuid.UUID(empresa_id)
    except ValueError:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Empresa no encontrada.",
        )


def _validate_date_range(fecha_inicio: date | None, fecha_fin: date | None) -> None:
    if fecha_inicio and fecha_fin and fecha_inicio > fecha_fin:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="fecha_inicio no puede ser mayor a fecha_fin.",
        )


@router.get(
    "/pendientes",
    response_model=ReportePendientesResponse,
    summary="Reporte de transacciones pendientes de liquidación",
    description=(
        "Lista todas las transacciones aprobadas y aún no liquidadas de una empresa, "
        "junto con el monto total acumulado. El resultado siempre está filtrado por "
        "`empresa_id`, garantizando que cada empresa solo acceda a sus propios datos. "
        "Opcionalmente se puede acotar el resultado a un rango de fechas de creación."
    ),
    responses={
        200: {"description": "Reporte generado correctamente."},
        400: {"description": "Rango de fechas inválido (fecha_inicio > fecha_fin)."},
        404: {"description": "Empresa no encontrada."},
    },
)
async def get_pending_report(
    empresa_id: str = Query(..., description="ID (UUID) de la empresa a consultar."),
    fecha_inicio: date | None = Query(
        None,
        description="Fecha de inicio del rango (YYYY-MM-DD). Incluye todo el día.",
    ),
    fecha_fin: date | None = Query(
        None,
        description="Fecha de fin del rango (YYYY-MM-DD). Incluye todo el día.",
    ),
    db: AsyncSession = Depends(get_db),
) -> ReportePendientesResponse:
    company_id = _parse_company_id(empresa_id)
    _validate_date_range(fecha_inicio, fecha_fin)
    service = ReportService(db)
    return await service.get_pending(company_id, fecha_inicio, fecha_fin)

import httpx

from app.config import settings
from app.models.models import TipoTarjeta


class CardServiceError(Exception):
    """Error técnico al comunicarse con el servicio de tarjetas (timeout, 5xx, red)."""


class CardClient:
    """Cliente HTTP para los servicios serverless de Visa y Mastercard."""

    TIMEOUT_SEGUNDOS = 5.0

    def __init__(self) -> None:
        self._urls = {
            TipoTarjeta.visa: f"{settings.VISA_SERVICE_URL}/visa/verificar-tarjeta",
            TipoTarjeta.mastercard: (
                f"{settings.MASTERCARD_SERVICE_URL}/mastercard/verificar-tarjeta"
            ),
        }

    async def verificar_tarjeta(
        self,
        tipo_tarjeta: TipoTarjeta,
        numero_tarjeta: str,
        cvv: str,
        fecha_expiracion: str | None = None,
    ) -> bool:
        """
        Llama al servicio serverless correspondiente y devuelve si la tarjeta existe.

        Lanza CardServiceError si el servicio no responde o devuelve un error
        técnico. Una tarjeta que simplemente no existe NO es un error: devuelve False.
        """
        url = self._urls[tipo_tarjeta]
        payload = {"numero_tarjeta": numero_tarjeta, "cvv": cvv}
        if tipo_tarjeta == TipoTarjeta.mastercard and fecha_expiracion:
            payload["fecha_expiracion"] = fecha_expiracion

        try:
            async with httpx.AsyncClient(timeout=self.TIMEOUT_SEGUNDOS) as client:
                response = await client.post(url, json=payload)
        except (httpx.TimeoutException, httpx.NetworkError) as exc:
            raise CardServiceError(
                f"Error al comunicarse con el servicio {tipo_tarjeta.value}: {exc}"
            ) from exc

        if response.status_code >= 500:
            raise CardServiceError(
                f"El servicio {tipo_tarjeta.value} respondió con error {response.status_code}"
            )

        response.raise_for_status()
        data = response.json()
        return bool(data.get("existe", False))

import logging
from datetime import datetime, timezone
from uuid import UUID

from fastapi import HTTPException, status
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

logger = logging.getLogger(__name__)

from app.models.models import Empresa, EstadoLiquidacion, Transaccion
from app.schemas.payment import LiquidacionBatchResponse


class LiquidationService:
    def __init__(self, db: AsyncSession) -> None:
        self.db = db

    async def liquidate_batch(self, company_id: UUID | None = None) -> LiquidacionBatchResponse:
        self._log_batch_start(company_id)
        if company_id is not None:
            await self._validate_company(company_id)

        transactions = await self._get_pending_transactions(company_id)
        ids = self._mark_as_liquidated(transactions)
        await self.db.flush()
        self._log_batch_complete(ids, company_id)
        return self._build_batch_response(ids)

    def _log_batch_start(self, company_id: UUID | None) -> None:
        logger.info(
            "Iniciando liquidación batch",
            extra={"empresa_id": str(company_id) if company_id else "todas"},
        )

    def _log_batch_complete(self, ids: list[UUID], company_id: UUID | None) -> None:
        logger.info(
            "Liquidación batch completada",
            extra={
                "procesadas": len(ids),
                "empresa_id": str(company_id) if company_id else "todas",
            },
        )

    async def _get_pending_transactions(self, company_id: UUID | None) -> list[Transaccion]:
        stmt = select(Transaccion).where(
            Transaccion.estado_liquidacion == EstadoLiquidacion.no_liquidado
        )
        if company_id is not None:
            stmt = stmt.where(Transaccion.empresa_id == company_id)

        result = await self.db.execute(stmt)
        return result.scalars().all()

    def _mark_as_liquidated(self, transactions: list[Transaccion]) -> list[UUID]:
        ids: list[UUID] = []
        for transaction in transactions:
            transaction.estado_liquidacion = EstadoLiquidacion.liquidado
            ids.append(transaction.id)
        return ids

    def _build_batch_response(self, ids: list[UUID]) -> LiquidacionBatchResponse:
        return LiquidacionBatchResponse(
            procesadas=len(ids),
            ids_liquidadas=ids,
            ejecutado_en=datetime.now(timezone.utc),
        )

    async def _validate_company(self, company_id: UUID) -> None:
        result = await self.db.execute(select(Empresa).where(Empresa.id == company_id))
        company = result.scalar_one_or_none()
        if company is None or not company.activo:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Empresa no encontrada.",
            )

import logging from datetime import date, datetime, time, timezone from decimal import Decimal from uuid import UUID
from fastapi import HTTPException, status from sqlalchemy import select from sqlalchemy.ext.asyncio import AsyncSession
logger = logging.getLogger(__name__)
from app.models.models import Empresa, EstadoLiquidacion, Transaccion from app.schemas.payment import ReportePendientesResponse, TransaccionReporteItem
class ReportService: def __init__(self, db: AsyncSession) -> None: self.db = db
async def get_pending( self, company_id: UUID, start_date: date | None, end_date: date | None, ) -> ReportePendientesResponse: self._log_report_start(company_id, start_date, end_date) company = await self._validate_company(company_id) transactions = await self._get_pending_transactions(company_id, start_date, end_date) total = self._sum_amounts(transactions) self._log_report_complete(company_id, transactions, total) return self._build_report_response(company, transactions, total)
def _log_report_start( self, company_id: UUID, start_date: date | None, end_date: date | None, ) -> None: logger.info( "Generando reporte de pendientes", extra={ "empresa_id": str(company_id), "fecha_inicio": str(start_date), "fecha_fin": str(end_date), }, )
def _log_report_complete( self, company_id: UUID, transactions: list[Transaccion], total: Decimal, ) -> None: logger.info( "Reporte generado", extra={ "empresa_id": str(company_id), "cantidad": len(transactions), "total_pendiente": str(total), }, )
async def _get_pending_transactions( self, company_id: UUID, start_date: date | None, end_date: date | None, ) -> list[Transaccion]: stmt = select(Transaccion).where( Transaccion.empresa_id == company_id, Transaccion.estado_liquidacion == EstadoLiquidacion.no_liquidado, )
if start_date: start_dt = datetime.combine(start_date, time.min).replace(tzinfo=timezone.utc) stmt = stmt.where(Transaccion.creado_en >= start_dt)
if end_date: end_dt = datetime.combine(end_date, time.max).replace(tzinfo=timezone.utc) stmt = stmt.where(Transaccion.creado_en <= end_dt)
result = await self.db.execute(stmt) return result.scalars().all()
def _sum_amounts(self, transactions: list[Transaccion]) -> Decimal: return sum((Decimal(str(t.monto)) for t in transactions), Decimal("0"))
def _build_report_response( self, company: Empresa, transactions: list[Transaccion], total: Decimal, ) -> ReportePendientesResponse: return ReportePendientesResponse( empresa_id=company.id, empresa_nombre=company.nombre, cantidad=len(transactions), total_pendiente=total, transacciones=[TransaccionReporteItem.model_validate(t) for t in transactions], )
async def _validate_company(self, company_id: UUID) -> Empresa: result = await self.db.execute(select(Empresa).where(Empresa.id == company_id)) company = result.scalar_one_or_none() if company is None: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Empresa no encontrada.", ) if not company.activo: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Empresa no encontrada.", ) return company
